{"command": "create", "path": "/workspace/pipelined_multiplier_tb.v", "file_text": "`timescale 1ns/1ps

module pipelined_multiplier_tb;
    reg clk;
    reg reset;
    reg [3:0] a;
    reg [3:0] b;
    wire [7:0] product;
    wire valid;

    pipelined_multiplier uut (
        .clk(clk),
        .reset(reset),
        .a(a),
        .b(b),
        .product(product),
        .valid(valid)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        #20;
        reset = 0;

        // Test all possible input combinations
        for (int i = 0; i < 16; i = i + 1) begin
            for (int j = 0; j < 16; j = j + 1) begin
                a = i;
                b = j;
                #30; // Wait for 3 clock cycles
                if (product !== i * j) begin
                    $fatal(1, "Test failed: %d * %d = %d, expected %d", i, j, product, i * j);
                end
                if (!valid) begin
                    $fatal(1, "Valid signal not asserted after 3 cycles");
                end
            end
        end

        $display("All tests passed successfully!");
        $finish;
    end
endmodule"}

